(function(){"use strict";const s=window.OasisAuth;if(!s.require(["cliente","master","atendedor"],"login.html?next=mis-vehiculos.html"))return;const o=s.current();document.getElementById("hello").textContent=`Hola, ${o.nombre}. C\xE9dula: ${o.cedula}. Aqu\xED est\xE1n tus reservas y su estado en tiempo real.`,document.getElementById("logoutBtn").onclick=()=>{s.logout(),location.href="index.html"};const l=e=>{if(!e)return null;const t=new Date(e+"T12:00:00");return Math.round((t.getTime()-Date.now())/864e5)};function u(e){const t=l(e.fechaRecogida),a=l(e.fechaRegreso),i=t===null?"\u2014":t>0?`Faltan ${t} d\xEDa${t===1?"":"s"}`:t===0?"Entrega hoy":`Entregada hace ${Math.abs(t)} d\xEDa${Math.abs(t)===1?"":"s"}`,n=a===null?"\u2014":a>0?`Te quedan ${a} d\xEDa${a===1?"":"s"} de renta`:"La renta finaliz\xF3",c=location.origin+location.pathname.replace("mis-vehiculos.html","reserva.html")+"?id="+encodeURIComponent(e.id),v=async()=>{const m=`Mi reserva Oasis: ${e.vehiculo} \xB7 ${e.fechaRecogida} al ${e.fechaRegreso} \xB7 Estado: ${e.status}`;if(navigator.share)try{await navigator.share({title:"Mi reserva Oasis",text:m,url:c});return}catch{}navigator.clipboard?.writeText(c+" \u2014 "+m);const r=document.getElementById("toast");r.textContent="Enlace copiado para compartir",r.classList.add("show"),setTimeout(()=>r.classList.remove("show"),2200)};return`<article class="reserva-card">
      <div style="display:flex;flex-wrap:wrap;justify-content:space-between;gap:.8rem;align-items:start">
        <div><p class="eyebrow">${e.usuarioId?"RESERVA "+e.id:e.id}</p><h3 style="font-size:1.8rem">${e.vehiculo}</h3></div>
        <span class="reserva-estado">${e.status}</span>
      </div>
      <div class="reserva-grid">
        <div><span style="font-size:.7rem;color:var(--muted)">RECOGIDA</span><b>${e.fechaRecogida||"\u2014"}</b></div>
        <div><span style="font-size:.7rem;color:var(--muted)">REGRESO</span><b>${e.fechaRegreso||"\u2014"}</b></div>
        <div><span style="font-size:.7rem;color:var(--muted)">LUGAR</span><b style="font-family:var(--font-body);font-size:.95rem">${e.pickup||"\u2014"}</b></div>
        <div><span style="font-size:.7rem;color:var(--muted)">PRECIO / D\xCDA</span><b>US $${e.precio}</b></div>
      </div>
      <div style="margin-top:1.2rem;display:flex;flex-wrap:wrap;gap:1.5rem;align-items:end">
        <div><p style="font-size:.7rem;color:var(--muted);margin:0">TIEMPO PARA LA ENTREGA</p><p class="countdown">${i}</p></div>
        <div><p style="font-size:.7rem;color:var(--muted);margin:0">DURACI\xD3N RESTANTE</p><p style="font-weight:700;margin:.4rem 0 0">${n}</p></div>
      </div>
      <div style="display:flex;flex-wrap:wrap;gap:.6rem;margin-top:1.2rem">
        <button class="btn btn-ghost btn-sm" data-share="${e.id}">COMPARTIR RESERVA \u2197</button>
        <a class="btn btn-orange btn-sm" href="https://wa.me/18096930840?text=${encodeURIComponent("Hola Oasis, tengo una reserva a mi nombre "+o.nombre+", c\xE9dula "+o.cedula+",ID "+e.id+".")}" target="_blank" rel="noopener">CONSULTAR POR WHATSAPP</a>
      </div>
    </article>`}const d=s.misReservas();document.getElementById("reservas").innerHTML=d.length?d.map(u).join(""):'<div class="panel"><h3>A\xFAn no tienes reservas</h3><p class="lede">Elige un veh\xEDculo y gu\xE1rdalo aqu\xED desde su p\xE1gina de detalle.</p><a class="btn btn-orange" href="index.html#vehiculos" style="margin-top:1rem">VER VEH\xCDCULOS \u2192</a></div>',document.querySelectorAll("[data-share]").forEach(e=>{e.onclick=()=>{const t=s.findReserva(e.dataset.share);if(!t)return;const a=location.href.split("?")[0].replace("mis-vehiculos.html","reserva.html")+"?id="+encodeURIComponent(t.id),i=`Mi reserva Oasis: ${t.vehiculo} \xB7 ${t.fechaRecogida} al ${t.fechaRegreso} \xB7 Estado: ${t.status}`;if(navigator.share)navigator.share({title:"Mi reserva Oasis",text:i,url:a}).catch(()=>{});else{navigator.clipboard?.writeText(a+" \u2014 "+i);const n=document.getElementById("toast");n.textContent="Enlace copiado",n.classList.add("show"),setTimeout(()=>n.classList.remove("show"),2200)}}})})();
